          sessionId: params.sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: { type: "text", text: line },
          } satisfies SessionUpdate,
        });

        reply(req.id, { stopReason: "end_turn" });
        return;
      }
      fail(req.id, -32601, `Method not found: ${req.method}`);
    } catch (err) {
      fail(req.id, -32603, err instanceof Error ? err.message : "Internal error");
    }
  }

export function runDecisionTurn(input: {
  sessionId: string;
  prompt: string;
  state?: State;
}): AcpTurnResult {
  const events: AcpTurnEvent[] = [];
  const sessionId = input.sessionId;
  const state =
    input.state ??
    ({
      user_prompt: input.prompt,
      agent_role: "coding-and-computer-use",
    } satisfies State);

  push(events, sessionId, {
    sessionUpdate: "plan",
    entries: [
      { content: "Ask Jev what kind of turn this is", priority: "high", status: "in_progress" },
      { content: "Confidence-gate before tools or computer use", priority: "high", status: "pending" },
      { content: "Let the LLM generate only if Jev says to", priority: "medium", status: "pending" },
    ],
  });

  const toolId = "jev_decide";
  push(events, sessionId, {
    sessionUpdate: "tool_call",
    toolCallId: toolId,
    title: "Jevbridge decide",
    kind: "other",
    status: "in_progress",
  });

  const looksComputer =
    /click|refund|browser|screen|ui|desktop|computer use/i.test(input.prompt);
  const decision = looksComputer
    ? evaluateHeuristic(
        typeof state === "object" && state && "visible_controls" in state
          ? state
          : observationState({
              goal: input.prompt,
              app: "Unknown",
              visible: ["Continue", "Cancel", "Back"],
            }),
        computerUseQuestions(["Continue", "Cancel", "Back"]),
      )
    : evaluateHeuristic(state, {
        task: choice("What is this turn?", {
          question: "The user wants an explanation or answer.",
          code_edit: "The user wants code changed.",
          computer_use: "The user wants a GUI or browser acted on.",
          terminal: "The user wants a shell command run.",
        }),
        needs_permission: noul("Should the agent ask before acting?"),
        risk: score("How risky is an unsupervised action?", [
          "Read-only",
          "Local reversible edit",
          "Shared or production effect",
        ]),
      });

  const decisionGate = gate(decision.answers, {
    choiceId: looksComputer ? "next_action" : "task",
    destructiveId: looksComputer ? "is_destructive" : undefined,
    noulId: looksComputer ? "is_safe" : "needs_permission",
  });

  const summary = JSON.stringify(
    {
      backend: decision.backend,
      answers: decision.answers,
      gate: decisionGate,
      action: looksComputer ? readAction(decision.answers) : undefined,
      target: looksComputer
        ? resolveTarget(decision.answers, ["Continue", "Cancel", "Back"])
        : undefined,
    },
    null,
    2,
  );

  push(events, sessionId, {
    sessionUpdate: "tool_call_update",
    toolCallId: toolId,
    status: "completed",
    content: [{ type: "content", content: { type: "text", text: summary } }],
  });

  const thought =
    decisionGate.action === "execute"
      ? "Jev is peaked. Proceed."
      : decisionGate.action === "confirm"
        ? "Jev wants a permission prompt before the tool runs."
        : decisionGate.action === "abort"
          ? "Jev aborted. Do not run the tool."
          : "Jev is uncertain. Escalate to the generating LLM.";

  push(events, sessionId, {
    sessionUpdate: "agent_thought_chunk",
    content: { type: "text", text: thought },
  });

  const message =
    decisionGate.action === "abort"
      ? `Stopped by Jevbridge (${decisionGate.reason})`
      : looksComputer
        ? `Next computer-use step: ${readAction(decision.answers)} — ${decisionGate.reason}`
        : `Routed as ${(decision.answers.task && decision.answers.task.type === "choice" ? decision.answers.task.choice : "task")} with gate ${decisionGate.action}.`;

  push(events, sessionId, {
    sessionUpdate: "agent_message_chunk",
    content: { type: "text", text: message },
  });

  return { events, stopReason: "end_turn", decision };
}

export async function evaluate(req: EvaluateRequest): Promise<EvaluateResult> {
  const backend = resolveBackend(req);
  if (backend === "heuristic") return evaluateHeuristic(req.state, req.questions);
  if (backend === "jev") {
    if (!req.jev?.apiKey) throw new Error("TYPESAFE_API_KEY is required for the Jev backend");
    return evaluateJev(req.state, req.questions, req.jev);
  }
  if (!req.llm?.apiKey) throw new Error("An LLM API key is required for the adapter backend");
  return evaluateLlm(req.state, req.questions, req.llm);
}

export function resolveBackend(req: EvaluateRequest): EvaluateResult["backend"] {
  if (req.backend && req.backend !== "auto") return req.backend;
  if (req.jev?.apiKey) return "jev";
  if (req.llm?.apiKey) return "llm";
  return "heuristic";
}

export function gate(answers: Answers, policy: GatePolicy = {}): GateDecision {
  const p = { ...DEFAULT, ...policy };
  const { value: confidence, choice } = confidenceOf(answers, p);
  const destructive = p.destructiveId
    ? pickNoul(answers, p.destructiveId)?.noul
    : undefined;
  const abortChoices = p.abortChoices ?? DEFAULT.abortChoices;
  const doneChoices = p.doneChoices ?? DEFAULT.doneChoices;

  if (choice && abortChoices.includes(choice)) {
    return { action: "abort", reason: `Jev selected ${choice}.`, confidence, choice, destructive };
  }
  if (choice && doneChoices.includes(choice)) {
    return { action: "execute", reason: "Goal complete.", confidence, choice, destructive };
  }
  if (confidence < p.abortBelow) {
    return {
      action: "abort",
      reason: "Confidence is too low to act or confirm.",
      confidence,
      choice,
      destructive,
    };
  }
  if (destructive !== undefined && destructive >= 0.62 && confidence < 0.88) {
    return {
      action: "confirm",
      reason: "Action looks destructive. Ask before executing.",
      confidence,
      choice,
      destructive,
    };
  }
  if (confidence >= p.executeAbove) {
    return {
      action: "execute",
      reason: "Distribution is peaked enough to act.",
      confidence,
      choice,
      destructive,
    };
  }
  if (confidence >= p.confirmAbove) {
    return {
      action: "confirm",
      reason: "Plausible, but not peaked. Request permission.",
      confidence,
      choice,
      destructive,
    };
  }
  return {
    action: "escalate",
    reason: "Hand back to the LLM or a human.",
    confidence,
    choice,
    destructive,
  };
}

