  const logits = keys.map((key) => {
    const desc = q.criteria[key] ?? "";
    const corpus = tokenize(`${key} ${desc} ${q.instructions}`);
    let score = overlap(corpus, bag) * 3;
    if (lower.includes(key.toLowerCase())) score += 2.2;
