export function evaluateHeuristic(state: State, questions: Questions): EvaluateResult {
  const started = Date.now();
  const stateText = flattenState(state);
  const bag = tokensFrom(state, Object.values(questions).map((q) => q.instructions).join(" "));
  const answers: Answers = {};
  for (const [id, q] of Object.entries(questions)) {
    if (q.type === "noul") answers[id] = { type: "noul", noul: noulFrom(q, bag) };
    else if (q.type === "choice") answers[id] = choiceFrom(q, bag, stateText);
    else answers[id] = scoreFrom(q, bag);
  }
  return {
    model: "jevbridge-heuristic",
    backend: "heuristic",
    answers,
    usage: {
      input_tokens: Math.ceil(stateText.length / 4),
      output_tokens: Object.keys(answers).length * 12,
      latency_ms: Date.now() - started,
    },
  };
}

function coerceOne(raw: unknown, q: Question): Answer {
  const obj = raw && typeof raw === "object" ? (raw as Record<string, unknown>) : {};
  if (q.type === "noul") {
    const n = Number(obj.noul ?? obj.value ?? obj.probability);
    return { type: "noul", noul: clamp01(n) };
  }
  if (q.type === "choice") {
    const keys = Object.keys(q.criteria);
    const incoming =
      obj.probabilities && typeof obj.probabilities === "object"
        ? (obj.probabilities as Record<string, number>)
        : {};
    const filled = Object.fromEntries(
      keys.map((k) => [k, Number(incoming[k] ?? (obj.choice === k ? 1 : 0))]),
    );
    const probabilities = normalizeMap(filled);
    const picked =
      typeof obj.choice === "string" && keys.includes(obj.choice)
        ? obj.choice
        : argmax(probabilities);
    return {
      type: "choice",
      choice: picked,
      confidence: clamp01(Number(obj.confidence) || peakedness(Object.values(probabilities))),
      probabilities,
    };
  }
  const n = q.criteria.length;
  const incoming =
    obj.probabilities && typeof obj.probabilities === "object"
      ? (obj.probabilities as Record<string, number>)
      : {};
  const filled = Object.fromEntries(
    Array.from({ length: n }, (_, i) => [String(i), Number(incoming[String(i)] ?? 0)]),
  );
  const probabilities = normalizeMap(filled);
  const legend = Object.fromEntries(q.criteria.map((label, i) => [String(i), label]));
  const score =
    Number.isFinite(Number(obj.score)) ? Number(obj.score) : expectedScore(probabilities);
  return {
    type: "score",
    score,
    confidence: clamp01(Number(obj.confidence) || peakedness(Object.values(probabilities))),
    legend,
    probabilities,
  };
}

export async function handleMcpRequest(req: JsonRpcRequest): Promise<JsonRpcResponse> {
  const { id, method, params } = req;
  try {
    if (method === "initialize") {
      const requested = (params as { protocolVersion?: string } | undefined)?.protocolVersion;
      return {
        jsonrpc: "2.0",
        id,
        result: {
          protocolVersion: negotiateVersion(requested),
          capabilities: {
            tools: { listChanged: false },
            resources: { listChanged: false },
            prompts: { listChanged: false },
          },
          serverInfo: SERVER_INFO,
          instructions: SERVER_INSTRUCTIONS,
        },
      };
    }
    if (method === "ping") {
      return { jsonrpc: "2.0", id, result: {} };
    }
    if (method === "tools/list") {
      return { jsonrpc: "2.0", id, result: { tools: MCP_TOOLS } };
    }
    if (method === "tools/call") {
      const call = (params ?? {}) as { name?: string; arguments?: unknown };
      if (!call.name) {
        return { jsonrpc: "2.0", id, error: { code: -32602, message: "name is required" } };
      }
      const result = await callMcpTool(call.name, call.arguments ?? {});
      return { jsonrpc: "2.0", id, result };
    }
    if (method === "resources/list") {
      return { jsonrpc: "2.0", id, result: { resources: MCP_RESOURCES } };
    }
    if (method === "resources/templates/list") {
      return { jsonrpc: "2.0", id, result: { resourceTemplates: [] } };
    }
    if (method === "resources/read") {
      const uri = (params as { uri?: string } | undefined)?.uri;
      if (!uri) {
        return { jsonrpc: "2.0", id, error: { code: -32602, message: "uri is required" } };
      }
      return { jsonrpc: "2.0", id, result: { contents: [readMcpResource(uri)] } };
    }
    if (method === "prompts/list") {
      return { jsonrpc: "2.0", id, result: { prompts: MCP_PROMPTS } };
    }
    if (method === "prompts/get") {
      const p = (params ?? {}) as { name?: string; arguments?: Record<string, unknown> };
      if (!p.name) {
        return { jsonrpc: "2.0", id, error: { code: -32602, message: "name is required" } };
      }
      return { jsonrpc: "2.0", id, result: getMcpPrompt(p.name, p.arguments) };
    }
    return { jsonrpc: "2.0", id, error: { code: -32601, message: `Method not found: ${method}` } };
  } catch (err) {
    return {
      jsonrpc: "2.0",
      id,
      error: { code: -32603, message: err instanceof Error ? err.message : "Internal error" },
    };
  }
}

function asArgs(value: unknown): Record<string, unknown> {
  if (value == null) return {};
  if (typeof value !== "object" || Array.isArray(value)) {
    throw new Error("tool arguments must be an object");
  }
  return value as Record<string, unknown>;
}

function backendOf(raw: unknown): BackendRequest {
  if (raw == null || raw === "auto" || raw === "jev" || raw === "llm" || raw === "heuristic") {
    return (raw ?? "auto") as BackendRequest;
  }
  throw new Error("backend must be auto, jev, llm, or heuristic");
}

function stringArg(raw: unknown, fallback?: string): string | undefined {
  if (raw == null) return fallback;
  if (typeof raw === "string") return raw;
  throw new Error("expected a string");
}

export async function callMcpTool(name: string, rawArgs: unknown): Promise<McpToolResult> {
  try {
    const args = asArgs(rawArgs);
    if (name === "jev_decide") {
      const questions = parseQuestions(args.questions);
      const result = await runEvaluate(asState(args.state), questions, backendOf(args.backend));
      const includeGate = args.gate !== false;
      if (!includeGate) {
        return ok({
          backend: result.backend,
          model: result.model,
          usage: result.usage,
          answers: result.answers,
        });
      }
      return ok(
        gated(result, {
          choiceId: stringArg(args.choiceId),
          destructiveId: stringArg(args.destructiveId),
        }),
      );
    }
    if (name === "jev_gate") {
      const policy: GatePolicy = {
        choiceId: stringArg(args.choiceId),
        noulId: stringArg(args.noulId),
        destructiveId: stringArg(args.destructiveId),
        executeAbove: typeof args.executeAbove === "number" ? args.executeAbove : undefined,
        confirmAbove: typeof args.confirmAbove === "number" ? args.confirmAbove : undefined,
        abortBelow: typeof args.abortBelow === "number" ? args.abortBelow : undefined,
        abortChoices: Array.isArray(args.abortChoices) ? (args.abortChoices as string[]) : undefined,
        doneChoices: Array.isArray(args.doneChoices) ? (args.doneChoices as string[]) : undefined,
      };
      return ok(gate(asAnswers(args.answers), policy));
    }
    if (name === "jev_computer_use") {
      const goal = stringArg(args.goal);
      if (!goal) throw new Error("goal is required");
      if (!Array.isArray(args.visible) || args.visible.some((item) => typeof item !== "string")) {
        throw new Error("visible must be an array of control labels");
      }
      const visible = args.visible as string[];
      const result = await runEvaluate(
        observationState({
          goal,
          app: stringArg(args.app) ?? "desktop",
          url: stringArg(args.url),
          visible,
          focused: stringArg(args.focused) ?? null,
          lastAction: stringArg(args.lastAction) ?? null,
          notes: stringArg(args.notes),
        }),
        computerUseQuestions(visible),
        backendOf(args.backend),
      );
      const decision = gate(result.answers, {
        choiceId: "next_action",
        destructiveId: "is_destructive",
      });
      return ok({
        action: readAction(result.answers),
        target: resolveTarget(result.answers, visible),
        gate: decision,
        backend: result.backend,
        model: result.model,
        answers: result.answers,
      });
    }
    if (name === "jev_recipe") {
      const id = stringArg(args.id);
      if (!id) throw new Error("id is required");
      const found = RECIPES.find((r) => r.id === id);
      if (!found) throw new Error(`unknown recipe: ${id}`);
      const result = await runEvaluate(found.state, found.questions, backendOf(args.backend));
      const choiceId =
        found.id === "computer-use" ? "next_action" : found.id === "destructive-gate" ? "next" : undefined;
      return ok({
        recipe: found.id,
        title: found.title,
        ...gated(result, {
          choiceId,
          destructiveId: "is_destructive" in found.questions ? "is_destructive" : undefined,
        }),
      });
    }
    return fail(`Unknown tool: ${name}`);
  } catch (err) {
    return fail(err instanceof Error ? err.message : "Tool failed");
  }
}

export function getMcpPrompt(name: string, args: Record<string, unknown> | undefined) {
  if (name === "jev_decide") {
    const state = typeof args?.state === "string" ? args.state : "<paste state>";
    return {
      description: "Call jev_decide on this state.",
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: `Call jev_decide. State:\n${state}\n\nAsk noul/choice/score questions. Then jev_gate before acting.`,
          },
        },
      ],
    };
  }
  if (name === "jev_computer_use") {
    const goal = typeof args?.goal === "string" ? args.goal : "<goal>";
    const visible = typeof args?.visible === "string" ? args.visible : "Continue, Cancel";
    return {
      description: "Call jev_computer_use on this observation.",
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: `Call jev_computer_use with goal ${JSON.stringify(goal)} and visible controls: ${visible}. Do not invent selectors. Obey the gate.`,
          },
        },
      ],
    };
  }
  throw new Error(`Unknown prompt: ${name}`);
}

export function clamp01(n: number): number {
  if (!Number.isFinite(n)) return 0;
  if (n < 0) return 0;
  if (n > 1) return 1;
  return n;
}

export function softmax(logits: number[], temperature = 0.7): number[] {
  const t = Math.max(0.05, temperature);
  const max = Math.max(...logits);
  const exps = logits.map((v) => Math.exp((v - max) / t));
  const sum = exps.reduce((a, b) => a + b, 0) || 1;
  return exps.map((v) => v / sum);
}

export function peakedness(probs: number[]): number {
  const n = probs.length;
  if (n <= 1) return 1;
  const h = -probs.reduce((s, p) => s + (p > 0 ? p * Math.log2(p) : 0), 0);
  const hMax = Math.log2(n);
  return clamp01(1 - h / hMax);
}

export function expectedScore(probabilities: Record<string, number>): number {
  return Object.entries(probabilities).reduce((sum, [k, p]) => {
    const i = Number(k);
    return sum + (Number.isFinite(i) ? i * p : 0);
  }, 0);
}

export function parseQuestion(id: string, raw: unknown): Question {
  const q = asRecord(raw, `questions.${id}`);
  const type = q.type;
  const instructions = q.instructions;
  if (typeof instructions !== "string" || instructions.trim().length === 0) {
    throw new Error(`questions.${id}.instructions must be a non-empty string`);
  }
  if (type === "noul") {
    const criteria = q.criteria;
    if (criteria == null) return { type: "noul", instructions };
    const rec = asRecord(criteria, `questions.${id}.criteria`);
    return {
      type: "noul",
      instructions,
      criteria: {
        true: typeof rec.true === "string" ? rec.true : null,
        false: typeof rec.false === "string" ? rec.false : null,
      },
    };
  }
  if (type === "choice") {
    const rec = asRecord(q.criteria, `questions.${id}.criteria`);
    const criteria: Record<string, string | null> = {};
    for (const [key, value] of Object.entries(rec)) {
      if (value != null && typeof value !== "string") {
        throw new Error(`questions.${id}.criteria.${key} must be a string or null`);
      }
      criteria[key] = value == null ? null : value;
    }
    if (Object.keys(criteria).length < 2) {
      throw new Error(`questions.${id} needs at least two choice criteria`);
    }
    return { type: "choice", instructions, criteria };
  }
  if (type === "score") {
    if (!Array.isArray(q.criteria) || q.criteria.some((item) => typeof item !== "string")) {
      throw new Error(`questions.${id}.criteria must be an array of rubric strings`);
    }
    if (q.criteria.length < 2) {
      throw new Error(`questions.${id} needs at least two score rubric entries`);
    }
    return { type: "score", instructions, criteria: q.criteria as string[] };
  }
  throw new Error(`questions.${id}.type must be noul, choice, or score`);
}
